42	  const specs = (sku && Array.isArray(sku.productSkuSpecList)) ? sku.productSkuSpecList : null;
43	  if (specs && specs.length) {
44	    return specs.map((sp) => String(sp.specName || sp.unitSpecName || '').trim()).filter(Boolean).join('/') || '';
