47	}
48	// 把单个 SKU 对象规范成统一结构
49	function normalizeSku(sku, product) {
50	  if (!sku || typeof sku !== 'object') return null;
51	  const skuId = sku.productSkuId || sku.skuId || sku.skuIdStr || sku.id || sku.skuSpecId || '';
52	  const name = formatSkuSpecName(sku);
53	  if (!skuId && !name) return null;
54	  return {
55	    skuId: skuId ? String(skuId) : '',
56	    name: name || ('SKU' + (skuId ? ' ' + skuId : '')),
57	    img: sku.thumbUrl || sku.skuImgUrl || sku.imageUrl || sku.imgUrl || '',
58	    productId: product && (product.productId || product.productIdStr) ? String(product.productId || product.productIdStr) : '',
59	    skc: product && (product.productSkcId || product.skcId) ? String(product.productSkcId || product.skcId) : '',
60	    productName: product && product.productName ? String(product.productName) : '',
61	    stock: typeof sku.realStock === 'number' ? sku.realStock
62	      : (typeof sku.virtualStock === 'number' ? sku.virtualStock : null),
63	  };
64	}
65	// 从 pageQuery 商品项提取 SKU 列表（真实字段：productSkuSummaries[].productSkuId + productSkuSpecList）
66	function extractSkusFromProduct(it) {
67	  if (!it || typeof it !== 'object') return [];
68	  const arr = Array.isArray(it.productSkuSummaries) ? it.productSkuSummaries
69	    : (Array.isArray(it.skuList) ? it.skuList
70	      : (Array.isArray(it.productSkus) ? it.productSkus : null));
71	  if (!arr) return [];
72	  return arr.map((sku) => normalizeSku(sku, it)).filter(Boolean);
73	}
74	function parsePageQuery(body) {
75	  try {
76	    const j = JSON.parse(body);
77	    const r = j && j.result;
78	    if (!r) return null;
79	    const pageItems = Array.isArray(r.pageItems) ? r.pageItems
80	      : (Array.isArray(r.list) ? r.list : []);
81	    const products = [];
82	    const flatSkus = [];
83	    for (const it of pageItems) {
84	      if (!it || typeof it !== 'object') continue;
85	      const productId = it.productId != null ? String(it.productId) : '';
86	      if (!productId) continue;
87	      const skus = extractSkusFromProduct(it);
88	      const product = {
89	        productId,
90	        skc: it.productSkcId != null ? String(it.productSkcId) : '',
91	        name: String(it.productName || '').slice(0, 80),
92	        skus,
93	        skuCount: skus.length,
94	      };
95	      products.push(product);
96	      for (const s of skus) flatSkus.push(s);
97	    }
98	    return {
99	      total: typeof r.total === 'number' ? r.total : null,
100	      products,
101	      pageSkus: flatSkus,
102	      pageSkuCount: flatSkus.length,
103	      multiSkuProducts: products.filter((p) => p.skuCount > 1),
104	    };
105	  } catch (e) { log.warn('parsePageQuery: failed to parse response'); return null; }
106	}
107	// 在未知 JSON 树里找「看起来像 SKU 列表」的数组（编辑页 parent/list 结构会漂移）
108	function findSkuLikeArray(node, depth) {
109	  if (depth > 6 || node == null) return null;
110	  if (Array.isArray(node)) {
111	    if (!node.length) return null;
112	    const sample = node.slice(0, 5).filter((x) => x && typeof x === 'object');
113	    if (sample.length && sample.every((x) =>
114	      x.productSkuId != null || x.skuId != null || x.productSkuSpecList != null
115	      || x.specName != null || x.skuSpecId != null)) {
116	      return node;
117	    }
118	    for (const el of node.slice(0, 20)) {
119	      const found = findSkuLikeArray(el, depth + 1);
120	      if (found) return found;
121	    }
122	    return null;
123	  }
124	  if (typeof node === 'object') {
125	    // 优先常见键
126	    for (const k of ['list', 'skuSpecList', 'skuSpecs', 'productSkuSummaries', 'skuList', 'data', 'records', 'items']) {
127	      if (Array.isArray(node[k])) {
128	        const found = findSkuLikeArray(node[k], depth + 1);
129	        if (found) return found;
130	      }
131	    }
132	    for (const k of Object.keys(node).slice(0, 30)) {
133	      const found = findSkuLikeArray(node[k], depth + 1);
134	      if (found) return found;
135	    }
136	  }
137	  return null;
138	}
139	function parseSkuSpecList(body) {
140	  try {
141	    const j = JSON.parse(body);
142	    // 1) 浅路径 2) 深搜「SKU 形」数组
143	    let list = j && j.result && j.result.list;
144	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecList;
145	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecs;
146	    if (!Array.isArray(list)) list = j && j.result && j.result.productSkuSummaries;
147	    if (!Array.isArray(list)) list = j && j.result && j.result.data;
148	    if (!Array.isArray(list)) list = j && j.result && Array.isArray(j.result) ? j.result : null;
149	    if (!Array.isArray(list)) list = j && j.data && j.data.list;
150	    if (!Array.isArray(list)) list = j && Array.isArray(j.data) ? j.data : null;
151	    if (!Array.isArray(list)) list = findSkuLikeArray(j, 0);
152	    if (!Array.isArray(list)) {
153	      log.warn('parseSkuSpecList: no sku-like array, result keys=' +
154	        (j && j.result ? Object.keys(j.result).slice(0, 12).join(',') : 'null'));
155	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
156	      return null;
157	    }
158	    const specs = list.map((it) => normalizeSku(it, null)).filter(Boolean);
159	    if (!specs.length) {
160	      log.warn('parseSkuSpecList: parsed ' + list.length + ' items but none had skuId/name, first item keys=' +
161	        (list[0] && typeof list[0] === 'object' ? Object.keys(list[0]).slice(0, 12).join(',') : typeof list[0]));
162	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
163	      return null;
164	    }
165	    return { skuSpecs: specs, skuSpecCount: specs.length };
166	  } catch (e) { log.warn('parseSkuSpecList: failed to parse response: ' + (e && e.message ? e.message : String(e))); return null; }
167	}
