200	// ---------------- 飞书 ----------------
201	// template：飞书卡片色条 red/orange/blue/green/turquoise/wathet/purple/violet/carmine/yellow/grey
202	async function sendFeishu(webhook, title, lines, template) {
203	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
204	  const card = {
205	    msg_type: 'interactive',
206	    card: {
207	      header: { title: { tag: 'plain_text', content: title }, template: template || 'red' },
208	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
209	    },
210	  };
211	  try {
212	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
213	    const data = await resp.json().catch(() => ({}));
214	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
215	    if (ok) log.info('Feishu sent OK: ' + title);
216	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
217	  } catch (e) {
218	    log.error('Feishu send FAILED: ' + (e && e.message ? e.message : 'unknown'));
219	    return { ok: false, msg: '发送失败：' + (e && e.message) };
220	  }
221	}
222	
223	// ---------------- 定时必提醒（每天固定时刻强制汇报各店状态） ----------------
224	function parseHHMM(s) {
225	  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
226	  if (!m) return null;
227	  const h = Number(m[1]);
228	  const min = Number(m[2]);
229	  if (h > 23 || min > 59) return null;
