    const p = parseSkuPriceQuery(msg.body);
    if (p) {
      log.info('skuPriceQuery captured: store=' + name);
      await updateStoreLatest(name, { skuPriceRaw: p.skuPriceRaw });
    }
  }
  sendResponse({ ok: true });
  return;
}
